package net.officefloor.hq.app.rate;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** Another user set the grade's rate at the same moment. */
@ResponseStatus(HttpStatus.CONFLICT)
public class RateConflictException extends RuntimeException {

    public RateConflictException() {
        super("The rate was changed at the same moment; try again.");
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.AsOf;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The sheet's rate for each grade. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/rates")
public class RateController {

    /** A grade's rate as the screen shows it: its from-date (YYYY-MM-DD, none when it applies from
     *  the beginning of time), its to-date (none when it applies on for good) and a percent with two
     *  decimals, the newest of its versions, with how many it has had. */
    public record RateView(String grade, String from, String to, String rate, int version) {

        static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getFromDate() == null ? null : rate.getFromDate().toString(),
                    rate.getToDate() == null ? null : rate.getToDate().toString(), rate.getRate().toPlainString(),
                    rate.getVersion());
        }
    }

    public record RateRequest(@NotNull @DecimalMin("0.00") @Digits(integer = 7, fraction = 2) BigDecimal rate,
            LocalDate from, LocalDate to) {
    }

    private final RateService service;
    private final AsOf asOf;

    public RateController(RateService service, AsOf asOf) {
        this.service = service;
        this.asOf = asOf;
    }

    /** The sheet's rates, by grade, each with its from-date; a grade with no rate is left out.; as they stood at the end of a date when the screen views the
     *  sheet as of one. */
    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestHeader(value = AsOf.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        return (asOf == null ? service.list(sheetId.trim()) : this.asOf.rates(sheetId.trim(), asOf)).stream()
                .map(RateView::of).toList();
    }

    /** The rates of each of the sheet's ancestors (its parent first, up to three levels up), each by grade;
     *  as they stood at the end of a date when the screen views the sheet as of one. */
    @GetMapping("/inherited")
    public List<List<RateView>> inherited(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestHeader(value = AsOf.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf == null) {
            return service.inherited(sheetId.trim()).stream().map(level -> level.stream().map(RateView::of).toList())
                    .toList();
        }
        return service.ancestors(sheetId.trim()).stream()
                .map(a -> this.asOf.rates(a, asOf).stream().map(RateView::of).toList()).toList();
    }

    /** Set a grade's rate from a date (or from the beginning of time), perhaps through a to-date,
     *  replacing the one it had then. */
    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid RateRequest request) {
        return RateView.of(service.set(sheetId.trim(), user.trim(), grade, request.from(), request.to(), request.rate()));
    }

    /** The rate import box's lines of grade,rate,from,to. */
    public record ImportRequest(@NotNull @Size(max = 1000000) String text) {
    }

    /** How many an import set, and the sheet's rates once they were. */
    public record ImportView(int set, List<RateView> rates) {
    }

    /** Set the rate each imported line names, in order; one refused line refuses them all. */
    @PostMapping("/import")
    public ImportView importRates(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid ImportRequest request) {
        int set = service.importRates(sheetId.trim(), user.trim(), request.text());
        return new ImportView(set, service.list(sheetId.trim()).stream().map(RateView::of).toList());
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.history.History;

/** The sheet's rate for a grade from a date (or from the beginning of time when it has none),
 *  perhaps through a to-date: a percent (0.00 or more, two decimals). */
@Entity
@EntityListeners(History.class)
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    /** The first day the rate applies; none when it applies from the beginning of time. */
    @Column(name = "from_date")
    private LocalDate fromDate;

    /** The last day the rate applies; none when it applies on for good. */
    @Column(name = "to_date")
    private LocalDate toDate;

    @Column(name = "rate", nullable = false)
    private BigDecimal rate;

    /** How many versions the rate has had: this, the newest, and the older ones it replaced. */
    @Column(name = "version", nullable = false)
    private int version = 1;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate fromDate, LocalDate toDate, BigDecimal rate) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.fromDate = fromDate;
        this.toDate = toDate;
        this.rate = rate;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public void setToDate(LocalDate toDate) {
        this.toDate = toDate;
    }

    /** Whether the rate still applies on a date on or after its from-date: not past its to-date. */
    public boolean coversThrough(LocalDate date) {
        return toDate == null || !date.isAfter(toDate);
    }

    public BigDecimal getRate() {
        return rate;
    }

    public void setRate(BigDecimal rate) {
        this.rate = rate;
    }

    public int getVersion() {
        return version;
    }

    /** Replace the rate with a newer version, through a to-date; the caller keeps the one it replaces. */
    public void newVersion(BigDecimal rate, LocalDate toDate) {
        this.rate = rate;
        this.toDate = toDate;
        this.version++;
    }
}
package net.officefloor.hq.app.rate;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** A rate that cannot be set as asked, such as one whose to-date is before its from-date. */
@ResponseStatus(HttpStatus.UNPROCESSABLE_ENTITY)
public class RateRefusedException extends RuntimeException {

    public RateRefusedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RateRepository extends JpaRepository<Rate, Long> {

    /** The sheet's rates, by grade. */
    List<Rate> findBySheetIdOrderByGradeAsc(String sheetId);

    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    /** The grade's rate with this from-date; none given finds the one with no from-date. */
    default Optional<Rate> findBySheetIdAndGradeAndFrom(String sheetId, String grade, LocalDate from) {
        return findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(r -> from == null ? r.getFromDate() == null : from.equals(r.getFromDate()))
                .findFirst();
    }

    /** The sheet's rates, by grade, followed by each ancestor's, nearest first: a grade with no rate in
     *  force on a date on a sheet takes the next sheet's (see {@code Rollup.inForce}). */
    default List<Rate> findWithAncestors(String sheetId, List<String> ancestors) {
        List<Rate> chain = new ArrayList<>(findBySheetIdOrderByGradeAsc(sheetId));
        ancestors.forEach(a -> chain.addAll(findBySheetIdOrderByGradeAsc(a)));
        return chain;
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps each sheet's rates for each grade, each from a date or from the beginning of time.
 *  perhaps through a to-date. Setting a grade's rate for a from-date it already has keeps the rate
 *  it replaces as an older version and makes the new one, with its to-date, the one in force. */
@Service
public class RateService {

    private final RateRepository rates;
    private final RateVersionRepository versions;
    private final SheetRepository sheets;
    private final Rollup rollup;
    private final Audit audit;

    public RateService(RateRepository rates, RateVersionRepository versions, SheetRepository sheets, Rollup rollup,
            Audit audit) {
        this.rollup = rollup;
        this.rates = rates;
        this.versions = versions;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        requireSheet(sheetId);
        return rates.findBySheetIdOrderByGradeAsc(sheetId);
    }

    /** The rates of each of the sheet's ancestors, nearest first, each by grade: a grade with no rate in force
     *  on a date on the sheet takes the first of them with one. */
    @Transactional(readOnly = true)
    public List<List<Rate>> inherited(String sheetId) {
        requireSheet(sheetId);
        return sheets.ancestors(sheetId).stream().map(rates::findBySheetIdOrderByGradeAsc).toList();
    }

    /** The sheet's ancestors, nearest first, up to three levels up. */
    @Transactional(readOnly = true)
    public List<String> ancestors(String sheetId) {
        requireSheet(sheetId);
        return sheets.ancestors(sheetId);
    }

    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        requireSheet(sheetId);
        if (to != null && from != null && to.isBefore(from)) {
            throw new RateRefusedException("A rate's to-date cannot be before its from-date.");
        }
        BigDecimal value = pct.setScale(2);
        Rollup.Snapshot before = rollup.take(sheetId);
        Rate rate = rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from).orElse(null);
        if (rate == null) {
            try {
                rate = rates.saveAndFlush(new Rate(sheetId, grade, from, to, value));
            } catch (DataIntegrityViolationException e) {
                // Another user set the same grade and from-date's first rate at the same moment.
                throw new RateConflictException();
            }
        } else {
            versions.save(new RateVersion(rate, user));
            rate.newVersion(value, to);
            rate = rates.saveAndFlush(rate);
        }
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user
                + " grade=" + grade + " rate=" + rate.getRate().toPlainString()
                + (from == null ? "" : " from=" + from)
                + (to == null ? "" : " to=" + to));
        rollup.recordChanges(sheetId, user, before);
        return rate;
    }

    /** One line of the rate import box: a grade's rate from a date through a date, either perhaps none. */
    private record ImportLine(String grade, BigDecimal pct, LocalDate from, LocalDate to) {
    }

    private static final Pattern GRADE = Pattern.compile("[ABC]");
    private static final Pattern PCT = Pattern.compile("\\d{1,7}(\\.\\d{1,2})?");

    /** Set the rate each line of grade,rate,from,to names (from and to may be left out or blank), in order,
     *  each as the rate form would; every line is checked first, and one refused line refuses them all.
     *  Blank lines are skipped. How many were set. */
    @Transactional
    public int importRates(String sheetId, String user, String text) {
        requireSheet(sheetId);
        List<ImportLine> lines = new ArrayList<>();
        String[] raw = text == null ? new String[0] : text.split("\\r?\\n");
        for (int i = 0; i < raw.length; i++) {
            if (!raw[i].isBlank()) {
                lines.add(parseImport(i + 1, raw[i]));
            }
        }
        if (lines.isEmpty()) {
            throw new RateRefusedException("Paste at least one line of grade,rate,from,to.");
        }
        for (ImportLine line : lines) {
            set(sheetId, user, line.grade(), line.from(), line.to(), line.pct());
        }
        return lines.size();
    }

    private static ImportLine parseImport(int number, String line) {
        String[] f = line.split(",", -1);
        if (f.length < 2 || f.length > 4) {
            throw importRefused(number, "write it as grade,rate,from,to.");
        }
        String grade = f[0].trim();
        if (!GRADE.matcher(grade).matches()) {
            throw importRefused(number, "the grade must be A, B or C.");
        }
        String pct = f[1].trim();
        if (!PCT.matcher(pct).matches()) {
            throw importRefused(number, "enter a rate of 0.00 or more, with up to two decimals.");
        }
        LocalDate from = importDate(number, f.length > 2 ? f[2] : "", "from-date");
        LocalDate to = importDate(number, f.length > 3 ? f[3] : "", "to-date");
        if (from != null && to != null && to.isBefore(from)) {
            throw importRefused(number, "a rate's to-date cannot be before its from-date.");
        }
        return new ImportLine(grade, new BigDecimal(pct), from, to);
    }

    private static LocalDate importDate(int number, String field, String what) {
        String d = field.trim();
        if (d.isEmpty()) {
            return null;
        }
        try {
            if (d.length() != 10) {
                throw new DateTimeParseException(d, d, 0);
            }
            return LocalDate.parse(d);
        } catch (DateTimeParseException e) {
            throw importRefused(number, "enter a " + what + " as YYYY-MM-DD, or leave it blank.");
        }
    }

    private static RateRefusedException importRefused(int number, String why) {
        return new RateRefusedException("Line " + number + ": " + why);
    }

    private void requireSheet(String sheetId) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** An older version of a rate: the value (and to-date) a later setting of the same grade and from-date
 *  replaced. */
@Entity
@Table(name = "rate_version")
public class RateVersion {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
